/// Specification: Checks if a positive 8-bit integer is a power of two.
#[verifier(spec)]
fn is_power_of_two(n: i8) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Specification: The “limited‐prime” predicate as per problem statement.
#[verifier(spec)]
fn is_limited_prime(p: i8) -> bool {
    if p <= 1 {
        false
    } else if p == 2 {
        true
    } else if p % 2 == 0 {
        false
    } else {
        true
    }
}

/// Specification: Returns `true` if the winner is “Ashishgup”
/// and `false` if it is “FastestFinger”.
#[verifier(spec)]
fn winner(n: i8) -> bool {
    if n == 1 {
        // n = 1 ⇒ FastestFinger
        false
    } else if n == 2 {
        // n = 2 ⇒ Ashishgup
        true
    } else if is_power_of_two(n) {
        // any power of two (>2) ⇒ FastestFinger
        false
    } else if n % 4 != 2 {
        // all odd numbers and multiples of 4 ⇒ Ashishgup
        true
    } else {
        // the only remaining case is n % 4 == 2
        let p = n / 2;
        // if p is limited‐prime ⇒ FastestFinger, else Ashishgup
        !is_limited_prime(p)
    }
}

